export default function Contact() {
  return (
    <div className="page">
      <h1>Contact us</h1>
      <div className="grid-3">
        <div className="info-card"><h3>Phone</h3><p>+212 05377-77408</p></div>
        <div className="info-card"><h3>Email</h3><p>contact@prestige-events.com</p></div>
        <div className="info-card"><h3>City</h3><p>Salé / Rabat / Casablanca</p></div>
      </div>
    </div>
  );
}
